svg.script:
window.animatronicFace = {
  moveEyes: function(x, y) {
    document.documentElement.style.setProperty('--eye-x', x + 'px');
    document.documentElement.style.setProperty('--eye-y', y + 'px');
  },
  openJaw: function(amount) {           // 0 (closed) .. 1 (fully open)
    var f = Math.max(0, Math.min(1, amount));
    document.documentElement.style.setProperty('--jaw-scale', 1 + f * 0.22);
  },
  reset: function() {
    this.moveEyes(0, 0);
    this.openJaw(0);
  }
};
